namespace XamlG.Syntax;

/// <summary>A half-open UTF-16 source interval.</summary>
public readonly record struct TextSpan
{
    public TextSpan(int start, int length)
    {
        if (start < 0) throw new ArgumentOutOfRangeException(nameof(start));
        if (length < 0 || start > int.MaxValue - length) throw new ArgumentOutOfRangeException(nameof(length));
        Start = start; Length = length;
    }
    public int Start { get; }
    public int Length { get; }
    public int End => Start + Length;
    public bool Contains(int position) => position >= Start && position < End;
    public bool Contains(TextSpan other) => other.Start >= Start && other.End <= End;
    public bool OverlapsWith(TextSpan other) => Start < other.End && other.Start < End;
    public static TextSpan FromBounds(int start, int end) => new(start, checked(end - start));
    public override string ToString() => $"[{Start}..{End})";
}

namespace XamlG.Syntax;

/// <summary>Names defined by the XML/XAML languages, not framework-specific type names.</summary>
public static class XamlNames
{
    public const string Language2006 = "http://schemas.microsoft.com/winfx/2006/xaml";
    public const string Language2009 = "http://schemas.microsoft.com/winfx/2009/xaml";
    public const string Xml = "http://www.w3.org/XML/1998/namespace";
    public const string Xmlns = "http://www.w3.org/2000/xmlns/";
    public const string Compatibility = "http://schemas.openxmlformats.org/markup-compatibility/2006";
    public static bool IsLanguage(string value) => value == Language2006 || value == Language2009;
}

namespace XamlG.Syntax;
public abstract record XamlSyntaxNode(TextSpan FullSpan)
{
    public TextSpan Span => FullSpan;
}

namespace XamlG.Syntax;
public sealed record XamlAttributeSyntax(string Name, string Value, TextSpan NameSpan, TextSpan ValueSpan, TextSpan Span, char Quote)
{
    public bool IsNamespace => Name == "xmlns" || Name.StartsWith("xmlns:", StringComparison.Ordinal);
    public string LocalName => Name.Substring(Name.IndexOf(':') + 1);
}

using System.Collections.Immutable;
namespace XamlG.Syntax;

public sealed record XamlElementSyntax(string Name, TextSpan NameSpan, TextSpan OpenTagSpan, TextSpan CloseTagSpan, ImmutableArray<XamlAttributeSyntax> Attributes, ImmutableArray<XamlSyntaxNode> Children, bool IsSelfClosing, TextSpan FullSpan) : XamlSyntaxNode(FullSpan)
{
    public string LocalName => Name.Substring(Name.IndexOf(':') + 1);
    public TextSpan EndNameSpan { get; init; }
    public IEnumerable<XamlElementSyntax> DescendantsAndSelf()
    {
        var pending = new Stack<XamlElementSyntax>(); pending.Push(this);
        while (pending.Count != 0)
        {
            var current = pending.Pop(); yield return current;
            for (var i = current.Children.Length - 1; i >= 0; i--)
                if (current.Children[i] is XamlElementSyntax element) pending.Push(element);
        }
    }
}

using System.Collections.Immutable;
namespace XamlG.Syntax;

/// <summary>Persistent namespace and XML-space scope. A child never mutates its parent.</summary>
public sealed class NamespaceScope
{
    public static NamespaceScope Empty { get; } = new(ImmutableDictionary<string, string>.Empty.WithComparers(StringComparer.Ordinal).Add("xml", XamlNames.Xml), ImmutableHashSet<string>.Empty.WithComparer(StringComparer.Ordinal), false);
    private NamespaceScope(ImmutableDictionary<string, string> bindings, ImmutableHashSet<string> ignored, bool preserve)
    { Bindings = bindings; IgnoredNamespaces = ignored; PreserveSpace = preserve; }
    public ImmutableDictionary<string, string> Bindings { get; }
    public ImmutableHashSet<string> IgnoredNamespaces { get; }
    public bool PreserveSpace { get; }
    public NamespaceScope Push(XamlElementSyntax element)
    {
        var bindings = Bindings; var ignored = IgnoredNamespaces; var preserve = PreserveSpace;
        foreach (var a in element.Attributes)
            if (a.IsNamespace) bindings = bindings.SetItem(a.Name == "xmlns" ? string.Empty : a.Name.Substring(6), a.Value);
        var result = new NamespaceScope(bindings, ignored, preserve);
        foreach (var a in element.Attributes)
        {
            var name = result.Expand(a.Name, true);
            if (name.Namespace == XamlNames.Xml && name.LocalName == "space") preserve = a.Value == "preserve" || a.Value != "default" && preserve;
            if (name.Namespace == XamlNames.Compatibility && name.LocalName == "Ignorable")
                foreach (var prefix in a.Value.Split(new[] { ' ', '\t', '\r', '\n' }, StringSplitOptions.RemoveEmptyEntries))
                    if (bindings.TryGetValue(prefix, out var ns)) ignored = ignored.Add(ns);
        }
        return new NamespaceScope(bindings, ignored, preserve);
    }
    public ExpandedName Expand(string name, bool attribute = false)
    {
        var colon = name.IndexOf(':');
        if (colon < 0) return new(attribute ? string.Empty : Bindings.TryGetValue(string.Empty, out var ns) ? ns : string.Empty, name);
        return new(Bindings.TryGetValue(name.Substring(0, colon), out var mapped) ? mapped : null, name.Substring(colon + 1));
    }
    public XamlAttributeSyntax? Directive(XamlElementSyntax element, string name)
    {
        foreach (var attribute in element.Attributes)
        {
            var expanded = Expand(attribute.Name, true);
            if (expanded.Namespace != null && XamlNames.IsLanguage(expanded.Namespace) && expanded.LocalName == name) return attribute;
        }
        return null;
    }
}

using System.Text;
namespace XamlG.Syntax;
public static class XmlWhitespace
{
    public static bool IsWhitespace(char c) => c is ' ' or '\t' or '\n' or '\r';
    public static string Normalize(string text, bool preserve) => preserve ? text : Collapse(text, true, true);
    public static string Collapse(string text, bool trimStart, bool trimEnd)
    {
        var output = new StringBuilder(text.Length); var pending = false;
        foreach (var c in text)
        {
            if (IsWhitespace(c)) { pending = true; continue; }
            if (pending && (output.Length > 0 || !trimStart)) output.Append(' ');
            pending = false; output.Append(c);
        }
        if (pending && !trimEnd && (output.Length > 0 || !trimStart)) output.Append(' ');
        return output.ToString();
    }
}

using System.Globalization;
using System.Text;
namespace XamlG.Syntax;

internal static class XmlEntityDecoder
{
    public static string Decode(string text, int sourceStart, Action<XamlDiagnostic> report, bool attribute)
    {
        var output = new StringBuilder(text.Length);
        for (var i = 0; i < text.Length; i++)
        {
            var c = text[i];
            if (c == '\r') { if (i + 1 < text.Length && text[i + 1] == '\n') i++; output.Append(attribute ? ' ' : '\n'); continue; }
            if (attribute && (c == '\n' || c == '\t')) { output.Append(' '); continue; }
            if (c != '&') { output.Append(c); continue; }
            var end = text.IndexOf(';', i + 1);
            if (end < 0 || end - i > 32) { report(new("XG0008", "Unterminated XML entity.", new(sourceStart + i, 1))); output.Append(c); continue; }
            var name = text.Substring(i + 1, end - i - 1);
            string? value = name switch { "lt" => "<", "gt" => ">", "amp" => "&", "apos" => "'", "quot" => "\"", _ => null };
            if (value == null && name.StartsWith("#", StringComparison.Ordinal))
            {
                var hex = name.StartsWith("#x", StringComparison.Ordinal);
                if (int.TryParse(name.Substring(hex ? 2 : 1), hex ? NumberStyles.AllowHexSpecifier : NumberStyles.None, CultureInfo.InvariantCulture, out var scalar) &&
                    (scalar is 9 or 10 or 13 || scalar >= 0x20 && scalar <= 0xD7FF || scalar >= 0xE000 && scalar <= 0xFFFD || scalar >= 0x10000 && scalar <= 0x10FFFF))
                    value = char.ConvertFromUtf32(scalar);
            }
            if (value == null)
            {
                report(new("XG0008", $"Unknown or invalid XML entity '&{name};'.", new(sourceStart + i, end - i + 1)));
                output.Append(text, i, end - i + 1);
            }
            else output.Append(value);
            i = end;
        }
        return output.ToString();
    }
}

using System.Collections.Immutable;
using System.Threading;
namespace XamlG.Syntax;

/// <summary>Error-recovering XML frontend. It never resolves entities, opens URIs, or loads types.</summary>
internal sealed class XamlParser
{
    private readonly string _text;
    private readonly XamlParseOptions _options;
    private readonly CancellationToken _cancellation;
    private readonly List<XamlDiagnostic> _diagnostics = new();
    private int _position;
    public XamlParser(string text, XamlParseOptions options, CancellationToken cancellation)
    { _text = text; _options = options; _cancellation = cancellation; }
    public (ImmutableArray<XamlSyntaxNode> Nodes, ImmutableArray<XamlDiagnostic> Diagnostics) Parse()
    {
        if (_text.Length > _options.MaximumCharacters)
        { Report("XG0001", "Document exceeds the configured source size limit.", 0, 0); return (ImmutableArray<XamlSyntaxNode>.Empty, _diagnostics.ToImmutableArray()); }
        var nodes = ImmutableArray.CreateBuilder<XamlSyntaxNode>();
        while (_position < _text.Length)
        {
            _cancellation.ThrowIfCancellationRequested();
            var start = _position;
            if (At("</"))
            { SkipThrough(">"); Report("XG0004", "Closing tag has no matching opening tag.", start, _position - start); nodes.Add(new XamlTriviaSyntax("InvalidCloseTag", new(start, _position - start))); }
            else nodes.Add(ParseNode(0));
            if (_position == start) _position++;
        }
        var roots = nodes.OfType<XamlElementSyntax>().ToArray();
        if (roots.Length == 0) Report("XG0002", "A XAML document requires a root element.", 0, 0);
        foreach (var extra in roots.Skip(1)) Report("XG0002", "A XAML document cannot contain multiple root elements.", extra.NameSpan.Start, extra.NameSpan.Length);
        foreach (var text in nodes.OfType<XamlTextSyntax>())
            if (!string.IsNullOrWhiteSpace(text.Value) && text.Value != "\uFEFF") Report("XG0002", "Text is not allowed outside the root element.", text.Span.Start, text.Span.Length);
        return (nodes.ToImmutable(), _diagnostics.ToImmutableArray());
    }
    private XamlSyntaxNode ParseNode(int depth)
    {
        _cancellation.ThrowIfCancellationRequested();
        var start = _position;
        if (At("<!--"))
        { _position += 4; var body = _position; var ended = SkipThrough("-->"); if (!ended) Report("XG0003", "Unterminated XML comment.", start, _position - start); return new XamlTriviaSyntax("Comment", new(start, _position - start)); }
        if (At("<![CDATA["))
        {
            _position += 9; var content = _position; var end = _text.IndexOf("]]>", _position, StringComparison.Ordinal);
            if (end < 0) { end = _text.Length; _position = end; Report("XG0003", "Unterminated CDATA section.", start, end - start); } else _position = end + 3;
            return new XamlTextSyntax(_text.Substring(content, end - content).Replace("\r\n", "\n").Replace('\r', '\n'), true, new(start, _position - start));
        }
        if (At("<?"))
        { _position += 2; if (!SkipThrough("?>")) Report("XG0003", "Unterminated processing instruction.", start, _position - start); return new XamlTriviaSyntax("ProcessingInstruction", new(start, _position - start)); }
        if (At("<!"))
        {
            var bracket = 0; char quote = '\0'; _position += 2;
            while (_position < _text.Length)
            {
                var c = _text[_position++];
                if (quote != '\0') { if (c == quote) quote = '\0'; continue; }
                if (c is '\'' or '"') quote = c; else if (c == '[') bracket++; else if (c == ']') bracket--; else if (c == '>' && bracket <= 0) break;
            }
            Report("XG0009", "DTD and entity declarations are not permitted in XAML.", start, _position - start);
            return new XamlTriviaSyntax("ForbiddenDeclaration", new(start, _position - start));
        }
        if (_text[_position] == '<') return ParseElement(depth);
        while (_position < _text.Length && _text[_position] != '<') _position++;
        return new XamlTextSyntax(XmlEntityDecoder.Decode(_text.Substring(start, _position - start), start, AddDiagnostic, false), false, new(start, _position - start));
    }
    private XamlElementSyntax ParseElement(int depth)
    {
        var start = _position++; var nameStart = _position; var name = ReadName();
        var nameSpan = new TextSpan(nameStart, _position - nameStart);
        if (name.Length == 0) Report("XG0004", "Expected an element name.", nameStart, 0);
        var attributes = ImmutableArray.CreateBuilder<XamlAttributeSyntax>();
        var names = new HashSet<string>(StringComparer.Ordinal); var selfClosing = false;
        while (_position < _text.Length)
        {
            _cancellation.ThrowIfCancellationRequested(); SkipWhitespace();
            if (At("/>")) { _position += 2; selfClosing = true; break; }
            if (At(">")) { _position++; break; }
            if (At("<")) { Report("XG0004", "Expected '>' before the next element.", _position, 0); break; }
            var attributeStart = _position; var attributeName = ReadName(); var attributeNameSpan = new TextSpan(attributeStart, _position - attributeStart);
            if (attributeName.Length == 0) { if (_position < _text.Length) { Report("XG0005", "Invalid attribute name.", _position, 1); _position++; } continue; }
            if (!names.Add(attributeName)) Report("XG0006", $"Duplicate attribute '{attributeName}'.", attributeStart, attributeName.Length);
            SkipWhitespace();
            if (!At("=")) { Report("XG0005", "Expected '=' after the attribute name.", _position, 0); attributes.Add(new(attributeName, string.Empty, attributeNameSpan, new(_position, 0), new(attributeStart, _position - attributeStart), '"')); continue; }
            _position++; SkipWhitespace();
            var quote = _position < _text.Length && (_text[_position] is '\'' or '"') ? _text[_position++] : '\0';
            var valueStart = _position;
            if (quote == '\0')
            {
                Report("XG0005", "Attribute values must be quoted.", _position, 0);
                while (_position < _text.Length && !XmlWhitespace.IsWhitespace(_text[_position]) && _text[_position] != '>' && !At("/>") && _text[_position] != '<') _position++;
            }
            else
            {
                while (_position < _text.Length && _text[_position] != quote && _text[_position] != '<') _position++;
                if (_position == _text.Length || _text[_position] != quote) Report("XG0005", "Unterminated attribute value.", valueStart, _position - valueStart);
            }
            var valueSpan = new TextSpan(valueStart, _position - valueStart);
            var value = XmlEntityDecoder.Decode(_text.Substring(valueStart, valueSpan.Length), valueStart, AddDiagnostic, true);
            if (quote != '\0' && _position < _text.Length && _text[_position] == quote) _position++;
            attributes.Add(new(attributeName, value, attributeNameSpan, valueSpan, new(attributeStart, _position - attributeStart), quote == '\0' ? '"' : quote));
        }
        var opening = new TextSpan(start, _position - start); var closing = new TextSpan(_position, 0); var closingName = closing;
        var children = ImmutableArray.CreateBuilder<XamlSyntaxNode>();
        if (!selfClosing)
        {
            if (depth >= _options.MaximumDepth)
            { Report("XG0001", "Document exceeds the configured nesting depth limit.", start, opening.Length); _position = _text.Length; }
            else
            {
                var closed = false;
                while (_position < _text.Length)
                {
                    _cancellation.ThrowIfCancellationRequested();
                    if (At("</"))
                    {
                        var closeStart = _position; var saved = _position; _position += 2; var closeNameStart = _position; var closeName = ReadName();
                        if (closeName != name)
                        {
                            _position = saved; Report("XG0007", $"Element '{name}' is not closed before '</{closeName}>'.", closeStart, 2 + closeName.Length); break;
                        }
                        closingName = new(closeNameStart, closeName.Length); SkipWhitespace();
                        if (At(">")) _position++; else Report("XG0004", "Expected '>' after the closing tag.", _position, 0);
                        closing = new(closeStart, _position - closeStart); closed = true; break;
                    }
                    var before = _position; children.Add(ParseNode(depth + 1)); if (_position == before) _position++;
                }
                if (!closed && _position >= _text.Length) Report("XG0007", $"Element '{name}' is missing a closing tag.", nameStart, name.Length);
            }
        }
        return new(name, nameSpan, opening, closing, attributes.ToImmutable(), children.ToImmutable(), selfClosing, new(start, _position - start)) { EndNameSpan = closingName };
    }
    private string ReadName()
    {
        var start = _position;
        while (_position < _text.Length)
        {
            var c = _text[_position];
            if (XmlWhitespace.IsWhitespace(c) || c is '<' or '>' or '/' or '=' or '\'' or '"' or '?' or '!') break;
            _position++;
        }
        return _text.Substring(start, _position - start);
    }
    private void SkipWhitespace() { while (_position < _text.Length && XmlWhitespace.IsWhitespace(_text[_position])) _position++; }
    private bool At(string value) => _position <= _text.Length - value.Length && string.CompareOrdinal(_text, _position, value, 0, value.Length) == 0;
    private bool SkipThrough(string terminal) { var end = _text.IndexOf(terminal, _position, StringComparison.Ordinal); _position = end < 0 ? _text.Length : end + terminal.Length; return end >= 0; }
    private void Report(string code, string message, int start, int length) => AddDiagnostic(new(code, message, new(start, length)));
    private void AddDiagnostic(XamlDiagnostic diagnostic) { if (_diagnostics.Count < _options.MaximumDiagnostics) _diagnostics.Add(diagnostic); }
}

using System.Collections.Immutable;
namespace XamlG.Syntax;
public sealed class SourceLineMap
{
    private readonly ImmutableArray<int> _starts;
    private readonly int _length;
    public SourceLineMap(string text)
    {
        _length = text.Length; var starts = ImmutableArray.CreateBuilder<int>(); starts.Add(0);
        for (var i = 0; i < text.Length; i++)
            if (text[i] == '\r') { if (i + 1 < text.Length && text[i + 1] == '\n') i++; starts.Add(i + 1); }
            else if (text[i] == '\n') starts.Add(i + 1);
        _starts = starts.ToImmutable();
    }
    public int LineCount => _starts.Length;
    public SourceLinePosition GetPosition(int offset)
    {
        if (offset < 0 || offset > _length) throw new ArgumentOutOfRangeException(nameof(offset));
        var low = 0; var high = _starts.Length - 1;
        while (low <= high) { var middle = low + (high - low) / 2; if (_starts[middle] <= offset) low = middle + 1; else high = middle - 1; }
        return new(high, offset - _starts[high]);
    }
    public int GetOffset(SourceLinePosition position)
    {
        if (position.Line < 0 || position.Line >= _starts.Length || position.Character < 0) throw new ArgumentOutOfRangeException(nameof(position));
        var end = position.Line + 1 < _starts.Length ? _starts[position.Line + 1] : _length;
        var offset = checked(_starts[position.Line] + position.Character);
        if (offset > end) throw new ArgumentOutOfRangeException(nameof(position));
        return offset;
    }
}

using System.Collections.Immutable;
using System.Text;
using System.Threading;
namespace XamlG.Syntax;

/// <summary>An immutable, source-preserving snapshot. Semantic work never changes the source tree.</summary>
public sealed class XamlSyntaxTree
{
    private XamlSyntaxTree(string text, string path, long version, XamlParseOptions options, ImmutableArray<XamlSyntaxNode> nodes, ImmutableArray<XamlDiagnostic> diagnostics)
    { Text = text; Path = path; Version = version; Options = options; Nodes = nodes; Diagnostics = diagnostics; Root = nodes.OfType<XamlElementSyntax>().FirstOrDefault(); Lines = new(text); }
    public string Text { get; }
    public string Path { get; }
    public long Version { get; }
    public XamlParseOptions Options { get; }
    public ImmutableArray<XamlSyntaxNode> Nodes { get; }
    public ImmutableArray<XamlDiagnostic> Diagnostics { get; }
    public XamlElementSyntax? Root { get; }
    public SourceLineMap Lines { get; }
    public bool HasErrors => Diagnostics.Any(d => d.Severity == XamlSeverity.Error);
    public static XamlSyntaxTree Parse(string text, string path = "", CancellationToken cancellationToken = default, XamlParseOptions? options = null, long version = 0)
    {
        if (text == null) throw new ArgumentNullException(nameof(text));
        options ??= new();
        if (options.MaximumDepth < 1 || options.MaximumCharacters < 1 || options.MaximumDiagnostics < 1) throw new ArgumentOutOfRangeException(nameof(options));
        var result = new XamlParser(text, options, cancellationToken).Parse();
        return new(text, path, version, options, result.Nodes, result.Diagnostics);
    }
    public XamlSyntaxTree WithChanges(IEnumerable<XamlTextChange> changes, long expectedVersion, CancellationToken cancellationToken = default)
    {
        if (expectedVersion != Version) throw new InvalidOperationException("The edit was computed for a stale source snapshot.");
        var ordered = changes.OrderBy(c => c.Span.Start).ToArray();
        var previousEnd = 0; var previousStart = -1;
        foreach (var change in ordered)
        {
            if (change.NewText == null || change.Span.End > Text.Length || change.Span.Start < previousEnd || change.Span.Start == previousStart) throw new ArgumentException("Edits must be in range and non-overlapping.", nameof(changes));
            previousEnd = change.Span.End; previousStart = change.Span.Start;
        }
        if (ordered.Length == 0) return this;
        var output = new StringBuilder(Text.Length); var offset = 0;
        foreach (var change in ordered) { cancellationToken.ThrowIfCancellationRequested(); output.Append(Text, offset, change.Span.Start - offset); output.Append(change.NewText); offset = change.Span.End; }
        output.Append(Text, offset, Text.Length - offset); var text = output.ToString();
        return text == Text ? this : Parse(text, Path, cancellationToken, Options, checked(Version + 1));
    }
    public XamlElementSyntax? FindElement(int position) => Root?.DescendantsAndSelf().Where(n => n.Span.Start <= position && n.Span.End >= position).OrderBy(n => n.Span.Length).FirstOrDefault();
    public override string ToString() => Text;
}

using System.Collections.Immutable;
namespace XamlG.Syntax;
public sealed record MarkupExtensionSyntax(string Name, ImmutableArray<MarkupArgumentSyntax> Arguments, TextSpan Span);

using System.Collections.Immutable;
namespace XamlG.Syntax;

/// <summary>Balanced markup-extension parser; braces inside quoted strings never affect nesting.</summary>
public static class MarkupExtensionParser
{
    public static MarkupExtensionSyntax? Parse(string text, TextSpan span, Action<XamlDiagnostic> report)
    {
        if (text.Length < 2 || text[0] != '{' || text.StartsWith("{}", StringComparison.Ordinal)) return null;
        var end = text.Length;
        if (text[end - 1] != '}') { report(new("XG0010", "Markup extension is missing a closing brace.", span)); } else end--;
        var position = 1; while (position < end && char.IsWhiteSpace(text[position])) position++;
        var nameStart = position;
        while (position < end && !char.IsWhiteSpace(text[position]) && text[position] != ',') position++;
        var name = text.Substring(nameStart, position - nameStart);
        if (name.Length == 0) { report(new("XG0010", "Markup extension requires a type name.", span)); return null; }
        while (position < end && char.IsWhiteSpace(text[position])) position++;
        if (position < end && text[position] == ',') position++;
        var arguments = ImmutableArray.CreateBuilder<MarkupArgumentSyntax>(); var names = new HashSet<string>(StringComparer.Ordinal); var sawNamed = false;
        while (position < end)
        {
            while (position < end && char.IsWhiteSpace(text[position])) position++;
            var start = position; var equals = -1; var depth = 0; char quote = '\0'; var escaped = false;
            while (position < end)
            {
                var c = text[position];
                if (escaped) { escaped = false; position++; continue; }
                if (c == '\\' && quote != '\0') { escaped = true; position++; continue; }
                if (quote != '\0') { if (c == quote) quote = '\0'; position++; continue; }
                if (c is '\'' or '"') quote = c;
                else if (c == '{' || c == '(' || c == '[') depth++;
                else if (c == '}' || c == ')' || c == ']') depth--;
                else if (depth == 0 && c == '=' && equals < 0) equals = position;
                else if (depth == 0 && c == ',') break;
                position++;
            }
            if (quote != '\0' || depth != 0) report(new("XG0010", "Unbalanced markup-extension argument.", new(span.Start + start, position - start)));
            var argumentSpan = new TextSpan(span.Start + start, position - start);
            string? key = equals < 0 ? null : text.Substring(start, equals - start).Trim();
            var value = text.Substring(equals < 0 ? start : equals + 1, position - (equals < 0 ? start : equals + 1)).Trim();
            if (value.Length >= 2 && (value[0] is '\'' or '"') && value[value.Length - 1] == value[0]) value = Unquote(value);
            if (key != null) { sawNamed = true; if (key.Length == 0 || !names.Add(key)) report(new("XG0010", "A named markup argument is empty or duplicated.", argumentSpan)); }
            else if (sawNamed) report(new("XG0010", "Positional arguments must precede named arguments.", argumentSpan));
            if (value.Length != 0 || key != null) arguments.Add(new(key, value, argumentSpan));
            if (position < end && text[position] == ',') position++;
        }
        return new(name, arguments.ToImmutable(), span);
    }
    private static string Unquote(string value)
    {
        var result = new System.Text.StringBuilder(value.Length - 2);
        for (var i = 1; i < value.Length - 1; i++) { if (value[i] == '\\' && i + 1 < value.Length - 1) i++; result.Append(value[i]); }
        return result.ToString();
    }
}

using System.Collections.Immutable;
namespace XamlG.Syntax;
public sealed record XamlTypeNameSyntax(string Name, ImmutableArray<XamlTypeNameSyntax> Arguments, bool Nullable, TextSpan Span);

using System.Collections.Immutable;
namespace XamlG.Syntax;
public static class XamlTypeNameParser
{
    public static XamlTypeNameSyntax? Parse(string text, TextSpan span, Action<XamlDiagnostic> report)
    {
        var values = ParseList(text, span, report);
        if (values.Length == 1) return values[0];
        if (values.Length > 1) report(new("XG0011", "Expected one type name.", span));
        return null;
    }
    public static ImmutableArray<XamlTypeNameSyntax> ParseList(string text, TextSpan span, Action<XamlDiagnostic> report)
    {
        var position = 0; var failed = false;
        void Space() { while (position < text.Length && char.IsWhiteSpace(text[position])) position++; }
        XamlTypeNameSyntax? Read(int depth)
        {
            Space(); var start = position;
